<script setup lang="ts">
import {computed,ref,shallowRef} from 'vue';
import {mdiClose} from '@mdi/js';
import type {StockRecord} from '../shared/types';
import {inventoryDeletionReason,type ArchivedInventory} from '../shared/inventory-archive';
const props=defineProps<{stock?:StockRecord;revision:string}>();
const emit=defineEmits<{reload:[];deleted:[];notify:[message:string]}>();
const confirm=ref<StockRecord|null>(null),showArchive=ref(false),archives=ref<ArchivedInventory[]>([]),selected=ref<ArchivedInventory|null>(null),busy=ref(false),error=ref('');
const opener=shallowRef<HTMLElement|null>(null);
function captureFocus(){opener.value=document.activeElement instanceof HTMLElement?document.activeElement:null;}
function restoreFocus(){if(opener.value?.isConnected)opener.value.focus();else document.getElementById('main-content')?.focus();}
let expected='';
const search=ref('');
const records=computed(()=>{const query=search.value.trim().toLowerCase();return archives.value.filter(entry=>[entry.component.name,entry.component.manufacturer,entry.stock.serial,entry.stock.assetTag,entry.stock.id].join(' ').toLowerCase().includes(query));});
const reason=computed(()=>props.stock?inventoryDeletionReason(props.stock):'');
function confirmDiscard(){if(busy.value)return false;confirm.value=null;showArchive.value=false;return true;}
defineExpose({hasUnsavedChanges:()=>busy.value,confirmDiscard});
function begin(){if(!props.stock)return;captureFocus();confirm.value=JSON.parse(JSON.stringify(props.stock));expected=props.revision;error.value='';}
async function remove(){if(!confirm.value||busy.value)return;busy.value=true;error.value='';try{const response=await fetch(`/api/inventory/${encodeURIComponent(confirm.value.id)}`,{method:'DELETE',headers:{'If-Match':expected}});const body=await response.json();if(!response.ok){if(response.status===409)emit('reload');throw Error(body.error||'Delete failed.');}confirm.value=null;emit('deleted');emit('reload');emit('notify','Inventory record deleted. Its component snapshot and history remain in Deleted records.');}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
async function loadArchive(){captureFocus();showArchive.value=true;selected.value=null;error.value='';busy.value=true;try{const response=await fetch('/api/inventory-archive');const body=await response.json();if(!response.ok)throw Error(body.error||'Could not load deleted records.');archives.value=body.records;}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
</script>
<template><div class="control-stack mb-4"><div class="heading-actions"><v-btn v-if="stock" color="error" variant="outlined" :disabled="!!reason||busy" @click="begin">Delete inventory record</v-btn><v-btn variant="text" :disabled="busy" @click="loadArchive">Deleted records</v-btn></div><p v-if="stock&&reason" class="form-hint">{{reason}}</p></div><v-dialog :activator="opener||undefined" :open-on-click="false" @after-leave="restoreFocus" :model-value="!!confirm" max-width="640" persistent aria-labelledby="inventory-delete-title" @keydown.esc.stop.prevent="confirmDiscard"><v-card v-if="confirm" class="editor-dialog"><v-card-title class="dialog-head"><h2 id="inventory-delete-title">Delete inventory record?</h2><v-btn :icon="mdiClose" variant="text" aria-label="Close inventory deletion" :disabled="busy" @click="confirmDiscard" /></v-card-title><v-card-text class="dialog-body"><v-alert v-if="error" type="error" role="alert">{{error}}</v-alert><p>{{confirm.serial||confirm.assetTag||confirm.id}} · {{confirm.quantity}} unit(s) · {{confirm.condition}}</p><p>This removes the record from current inventory. Its {{confirm.history.length}} history entries and component specifications stay in Deleted records and JSON backups, and will no longer block catalog deletion.</p></v-card-text><v-card-actions class="dialog-footer"><v-btn :disabled="busy" @click="confirmDiscard">Cancel</v-btn><v-btn color="error" :loading="busy" @click="remove">Delete record</v-btn></v-card-actions></v-card></v-dialog><v-dialog :activator="opener||undefined" :open-on-click="false" @after-leave="restoreFocus" v-model="showArchive" scrollable max-width="1100" aria-labelledby="inventory-archive-title"><v-card class="editor-dialog"><v-card-title class="dialog-head"><h2 id="inventory-archive-title">Deleted inventory records</h2><v-btn :icon="mdiClose" variant="text" aria-label="Close deleted records" @click="showArchive=false" /></v-card-title><v-card-text class="dialog-body"><v-alert v-if="error" type="error" role="alert">{{error}}</v-alert><p>Read-only records retain their original component specifications and movement history.</p><v-progress-linear v-if="busy" indeterminate /><v-text-field :model-value="search" label="Search deleted records" clearable @update:model-value="v=>search=String(v??'')" /><v-data-table :items="records" :sort-by="[{key:'at',order:'desc'}]" :headers="[{title:'Component',key:'component.name'},{title:'Serial / lot',key:'stock.assetTag'},{title:'Deleted',key:'at'},{title:'Details',key:'details',sortable:false}]" :mobile="false" :items-per-page="10"><template #caption><caption class="sr-only">Deleted inventory records and retained history</caption></template><template #item.stock.assetTag="{item}">{{item.stock.serial||item.stock.assetTag||item.stock.id}}</template><template #item.at="{item}">{{new Date(item.at).toLocaleString()}}</template><template #item.details="{item}"><v-btn variant="text" @click="selected=item">View record<span class="sr-only"> {{item.stock.id}}</span></v-btn></template></v-data-table><pre v-if="selected" class="snapshot-json" tabindex="0" aria-label="Deleted inventory record and component snapshot">{{JSON.stringify(selected,null,2)}}</pre></v-card-text></v-card></v-dialog></template>
